window.DOSIK=window.DOSIK||{};DOSIK["nm_biz"]={"1":[{"t":"table","title":"고전적 경영이론","head":["학자","내용"],"rows":[["테일러의 과학적 관리법","시간·동작 연구로 과업을 정하고 개인별 차별적 성과급, 기능적 직장제도, 과학적 선발·훈련, 관리자와 작업자의 협력과 분업을 내세우며 고임금 저노무비를 지향한다 · 보상 단위는 집단이 아니라 개인이다"],["포드","이동조립법으로 고임금 저가격을 제시했다"],["페이욜","관리 5요소와 권한·책임의 원칙을 제시했다"],["베버","규칙과 절차 중심의 관료제를 제시했다"]]},{"t":"flow","title":"호손실험","steps":["조명실험","계전기 조립실험","면접실험","배전기 전선작업실(뱅크선) 관찰 순서로 진행되었다","비공식조직과 사회적 요인이 작업능률을 좌우한다는 점을 밝혔고, 경제적 욕구보다 집단 규범이 중요하다는 결론이 인간관계론의 출발이 되었다"]},{"t":"table","title":"경영자와 기업","head":["구분","내용"],"rows":[["경영자 기술(카츠)","경영자 기술을 전문적(실무)·인간적·개념적 기술로 나누었고, 개념적 기술은 조직 전체를 종합적으로 파악하는 능력으로 상위 경영자일수록 중요하다"],["경영자 역할(민츠버그)","대인관계(대표자·리더·연락자), 정보(모니터·전파자·대변인), 의사결정(기업가·문제해결자·자원배분자·협상자) 역할이다"],["조직화","관리과정 중 역할 구조와 권한 관계를 정하는 단계는 조직화다"],["합명회사·합자회사","합명회사는 무한책임사원만, 합자회사는 무한책임사원(경영 담당)과 유한책임사원으로 구성된다"],["기업결합","관련 없는 업종을 인수·합병한 복합기업이 컨글로메리트이고, 같은 업종 기업의 협정은 카르텔이다"],["외부환경","경제·정치·사회문화·기술은 일반환경, 공급자·고객·경쟁자는 과업환경이다"],["규모의 비경제","생산규모가 커져 관료화로 평균비용이 오르는 현상은 규모의 비경제다"]]},{"t":"table","title":"경영전략","head":["전략","내용"],"rows":[["앤소프 제품-시장 매트릭스","기존 제품·기존 시장은 시장침투(사용률 증대 캠페인 포함), 기존 제품·신시장은 시장개발, 신제품·기존 시장은 제품개발, 신제품·신시장은 다각화다 · 새로운 시장을 대상으로 하는 전략은 시장개발과 다각화다"],["포터의 5요인","기존 경쟁자 간 경쟁, 잠재적 진입자, 대체재, 공급자 교섭력, 구매자 교섭력이 산업의 수익성을 정한다 · 진입장벽이 높고 경쟁이 약할수록 매력도가 높고, 대체재 위협·공급자 교섭력·구매자 교섭력이 강할수록 매력도가 낮다"],["본원적 전략","원가우위(생산비를 낮춘 가격경쟁력), 차별화, 집중화다"],["가치사슬","주요활동은 물류투입, 운영(생산), 물류산출, 마케팅·판매, 서비스다 · 보조활동은 기업 하부구조(기획·재무·법률), 인적자원관리, 기술개발(디자인 포함), 조달이다"],["BCG 매트릭스","별은 성장률과 상대적 점유율이 모두 높아 투자가 많이 필요하고, 현금젖소는 성장률이 낮고 점유율이 높아 현금 창출이 많다 · 물음표는 선별적 투자, 개는 철수 대상이다"],["마일즈와 스노우","공격형은 유연하고 분권화된 학습지향 구조, 방어형은 효율 중심의 집권적 구조, 분석형은 그 혼합, 반응형은 일관된 전략이 없다"],["BSC","균형성과표는 재무, 고객, 내부 프로세스, 학습과 성장의 4관점이다"],["캐롤의 피라미드","경제적(1단계)·법적·윤리적·자선적 책임 순이며 경제적·법적 책임은 의무, 윤리적·자선적 책임은 자발성에 기초하고 기본 단계를 먼저 이행한다"],["정의론적 관점","같은 기여에 같은 보상을 주는 것은 정의론적 관점이다"],["아웃소싱","외부 자원을 활용하고 핵심 업무에 집중하는 기법은 아웃소싱이다"]]}],"2":[{"t":"table","title":"동기 이론","head":["이론","내용"],"rows":[["매슬로우","생리적·안전·사회적·존경·자아실현의 5단계이고 하위 욕구가 충족되어야 상위 욕구가 동기가 된다 · 존경 욕구까지는 결핍욕구, 자아실현은 성장욕구다"],["허츠버그 2요인 이론","임금·작업조건·감독은 위생요인, 성취·인정·직무 자체는 동기요인이다"],["브룸의 기대이론","동기는 기대·수단성·유의성의 곱으로 정해지고, 조직 신뢰가 클수록 수단성이 높으며 유의성은 사람마다 다르다"],["아담스의 공정성이론","불공정을 줄이는 방법은 투입·산출 변경, 인지적 왜곡, 준거인물 변경, 장 이탈이다"],["인지평가이론","내재적 동기에 외재적 보상을 더하면 동기가 오히려 줄 수 있다고 본다"]]},{"t":"vs","title":"맥그리거의 X이론과 Y이론","cols":[{"name":"X이론","items":["통제·강제가 필요하다고 본다"]},{"name":"Y이론","items":["조건이 갖춰지면 일을 자연스럽게 여기고 자율적으로 일한다고 본다"]}]},{"t":"table","title":"강화·귀인·태도·성격","head":["구분","내용"],"rows":[["변동비율법","강화계획 중 변동비율법은 불규칙한 횟수의 행동 뒤에 강화한다"],["고정·변동간격법","시간 간격 기준이다"],["켈리의 귀인이론","합의성·특이성·일관성으로 원인을 판단하며 한 과목에서만 성적이 나쁘면 특이성이 높아 외부 귀인하기 쉽다"],["태도","인지적(믿음)·감정적(좋고 싫음)·행동적(의도) 요소로 구성된다"],["핵심자기평가","자존감, 일반화된 자기효능감, 통제위치, 정서적 안정성으로 구성된다"],["로키치의 가치","최종가치는 편안한 삶·행복·즐거움 같은 최종 상태이고, 야망·용기는 수단가치다"],["감정","특정 사건으로 생겨 강렬하고 기분보다 짧다"],["감정부조화","실제감정과 표현감정의 불일치는 감정부조화이고, 내면 연기가 피상적 연기보다 소진이 적다"]]},{"t":"table","title":"리더십·권력·집단·스트레스","head":["구분","내용"],"rows":[["행동이론","블레이크와 무튼의 관리그리드는 행동이론이다"],["상황이론","피들러, 하우스의 경로-목표이론, 허시와 블랜차드, 브룸과 예튼은 상황이론이다"],["변혁적 리더십","이상적 영향력, 영감적 동기부여(비전·높은 기대·상징), 지적 자극, 개인화된 배려로 구성되고 예외에 의한 관리는 거래적 리더십이다"],["서번트 리더십","구성원에 대한 봉사에 초점을 둔다"],["슈퍼리더십","구성원이 스스로를 관리하게 하는 데 초점을 둔다"],["프렌치와 레이븐의 권력","준거적·전문적 권력은 개인적 원천이고, 강제적·보상적·합법적 권력은 직위에서 나온다"],["심리적 임파워먼트(스프라이처)","의미, 역량, 자기결정, 영향력의 4차원이다"],["토마스-킬만 모형","협조성은 낮고 자기주장이 높은 유형은 경쟁형이다"],["애쉬의 동조실험","규범의 영향을 보여 준다"],["짐바르도의 감옥실험","역할의 영향을 보여 준다"],["집단 의사결정","정보가 다양하고 수용도·교육효과가 높지만 비판 없이 동의하는 집단사고와 차선책 채택 오류가 생길 수 있다"],["휴리스틱","경험 규칙으로 비구조적 문제를 푸는 기법이다 · 쉽게 떠오르는 정보로 판단하는 편향은 가용성 편향이다"],["직무스트레스","원인은 환경·조직·개인 요인이고 사회적 지지는 조정변수이며 결과는 생리적·심리적·행동적 증상이다 · 스트레스와 성과의 관계는 역U자형이다"],["의사소통 장애","정보 과부하는 수신자 측 장애이고, 기술 부족·준거체계 차이·목적 결여·신뢰성 부족은 발신자 측 장애다"]]}],"3":[{"t":"table","title":"구조 변수와 기술","head":["구분","내용"],"rows":[["기본변수","조직구조의 기본변수는 복잡성, 공식화, 집권화다"],["상황변수","조직설계의 상황변수는 환경, 전략, 기술, 규모다"],["번스와 스토커","환경이 안정적이면 공식화·집권화가 높은 기계적 구조, 불확실하면 분권화된 유기적 구조가 맞는다"],["우드워드","생산기술을 단위소량생산, 대량생산, 연속공정생산으로 나눴다"],["페로우","과업다양성과 분석가능성으로 일상적 기술(다양성 낮음·분석 쉬움), 공학기술(둘 다 높음), 장인기술(둘 다 낮음), 비일상적 기술(다양성 높음·분석 어려움)로 나눴다"]]},{"t":"tree","title":"민츠버그 조직유형","root":"민츠버그 조직유형","branches":[["단순구조"],["기계적 관료제"],["전문적 관료제"],["사업부제"],["애드호크라시"]]},{"t":"def","term":"매트릭스 조직","text":"이 분류에 없다 · 기능과 사업의 이중 명령 체계를 둔다"},{"t":"table","title":"조직 이론과 문화","head":["구분","내용"],"rows":[["기능별 조직","전문화와 규모의 경제에 유리하다"],["사업부제","제품·지역별 자율성과 책임이 분명하다"],["네트워크 조직","핵심 기능만 남기고 나머지를 외부와 계약으로 연결해 관리 비용이 적고 큰 설비 투자 없이 세계의 자원을 활용할 수 있다"],["자원의존 이론","생존에 필요한 자원을 확보하고 의존을 줄이려 환경에 영향력을 행사한다고 본다"],["조직군 생태학 이론","환경이 조직 형태를 선택·도태시키며 변이·선택·보존을 거치고, 대규모 조직은 관성 때문에 적응이 어렵다고 본다"],["제도화 이론","정당성을 얻으려 제도적 환경을 닮아 간다고 본다"],["거래비용 이론","거래비용을 줄이는 쪽으로 조직 경계가 정해진다고 본다"],["경계연결","조직 경계에서 외부 개인·집단과 접촉해 환경 정보를 얻고 조직을 대표하는 활동이다"],["조직개발","변화담당자의 도움으로 설계·실시·평가하는 체계적·계획적 변화기법으로 조직 전체의 변화를 지향한다"],["레윈","변화과정을 해빙, 변화, 재동결의 3단계로 설명했다"],["샤인","조직문화를 눈에 보이는 인공물, 표방하는 가치, 당연하게 받아들이는 기본 가정의 세 수준으로 설명했다"],["강한 문화","행동의 일관성과 몰입을 높이지만 환경 변화에 대한 적응을 늦출 수 있다"]]}],"4":[{"t":"table","title":"직무분석과 직무평가","head":["구분","내용"],"rows":[["직무기술서·직무명세서","직무분석으로 직무 내용을 정리한 것이 직무기술서, 수행자에게 필요한 자격요건을 정리한 것이 직무명세서다"],["직무분석","직무평가는 직무분석 결과를 토대로 하고, 직무분석은 인력확보·안전사고 예방에도 쓰인다"],["직무 충실화","계획·통제 책임과 자율성을 더하는 수직적 확대로 성취감을 높이며 허츠버그의 동기요인에 근거한다"],["서열법","직무 전체를 서로 비교하는 비계량적 방법이다"],["분류법","미리 정한 등급 기준에 비춰 분류한다"],["점수법과 요소비교법","계량적 방법이다"],["직무급","직무의 상대적 가치로 임금을 정해 동일노동 동일임금을 실현하고 능력주의에 유리하지만 절차가 복잡하다"]]},{"t":"table","title":"인력계획과 선발","head":["구분","내용"],"rows":[["질적 수요예측","브레인스토밍, 명목집단법, 델파이(전문가 의견 종합), 시나리오 기법(예측이 어려운 복잡한 환경), 자격요건 분석법이고 노동과학적 기법은 양적 기법이다"],["마코브 분석","공급예측의 마코브 분석은 인력 변동이 적고 안정적일 때 효과적이다"],["대체도·기능목록","대체도는 공석에 이동할 사람을, 기능목록은 종업원의 교육·경험·능력을 요약한다"],["내부모집","승진 기회 확대로 동기를 주고 평가가 정확하며 비용이 적지만 외부 인력이 차단되어 조직이 정체되고 파벌이 생길 수 있다"],["외부모집","창의성·혁신과 양적 충원은 외부모집의 장점이다"],["선발도구","업무 성과 예측(타당성), 반복 측정 일관성(신뢰성), 다른 상황 적용(일반화), 조직 효과성(유용성)으로 검토한다"],["면접","구조화 면접은 표준화된 질문지를 쓰고, 집단면접에서는 맥락효과가 생길 수 있다"]]},{"t":"table","title":"인사고과와 승진","head":["구분","내용"],"rows":[["상동적 오류","피평가자가 속한 집단에 대한 고정관념으로 평가하는 것은 상동적 오류다"],["중심화 경향","평가방법을 모르거나 차이를 가려내지 못해 중간 점수를 주는 것은 중심화 경향이다"],["후광(현혹)효과","한 특성의 인상이 다른 특성에 번지는 것은 후광(현혹)효과다"],["BOS","행동관찰척도법(BOS)은 중요사건기록법과 척도법을 결합해 구체적 행동의 빈도를 평가한다"],["BARS","행동기준척도법(BARS)은 행동 수준을 기준 사례에 비춰 평가한다"],["연공 승진","숙련이 연공에 비례할 때 적합하고 노동조합이 선호하며 능력주의는 경영자가 선호한다"],["직능자격승진","직급과 직능등급이 일치하지 않을 수 있다"],["대용승진","직무 변화 없이 명칭만 바뀐다"],["조직변화승진","조직을 바꿔 승진 기회를 만든다"],["홀의 경력단계","탐색, 확립, 유지, 쇠퇴 순이다"]]},{"t":"table","title":"임금관리와 노사관계","head":["구분","내용"],"rows":[["임금의 구분","임금수준은 크기, 임금체계는 결정 기준(연공급·직무급·직능급), 임금형태는 계산·지급 방법이다"],["연공급","사람 기준이어서 고용안정과 생활보장에 도움이 되지만 동일노동 동일임금이 어렵고 전문인력 유지가 어렵다"],["집단성과배분제","스캔론 플랜은 판매가치 대비 인건비 절약분을, 럭커 플랜은 부가가치를 기준으로 배분하는 집단성과배분제다"],["업적급·브로드밴드","업적급은 평가 등급에 따라 인상률을 달리하고, 브로드밴드는 등급 수가 줄어 승진 기회가 축소된다"],["고정상여금","고정상여금은 통상임금에 포함된다"],["법정복리후생","4대 보험 부담금, 퇴직금, 유급휴가처럼 법이 의무로 정한 것이다"],["유니온 숍·에이전시 숍","유니온 숍은 채용 후 자동으로 노조에 가입하고, 에이전시 숍은 비조합원에게도 조합비를 징수한다"],["노조 유형","직종별 노조는 숙련공 중심의 초기 형태, 산업별 노조는 압력단체 성격, 기업별 노조는 우리나라의 주된 형태다"],["대각선 교섭","산별노조와 개별 기업 사용자의 교섭은 대각선 교섭이다"]]}],"5":[{"t":"flow","title":"마케팅 관리철학의 발전","steps":["생산 개념(대량생산·원가절감, 유통 효율화)","제품 개념","판매 개념(적극적 판매·촉진, 판매량 증대) · 판매 개념은 소비자가 자발적으로 사지 않는 제품에서 흔하다","마케팅 개념(고객욕구 중심의 통합 마케팅, 고객만족)","사회지향적 마케팅 개념(사회 전체 복리)"]},{"t":"table","title":"수요 상황별 마케팅과 세분화","head":["구분","내용"],"rows":[["디마케팅","수요가 공급을 초과할 때 수요를 줄이는 것은 디마케팅이다"],["전환적 마케팅","부정적 수요를 바꾸는 것은 전환적 마케팅이다"],["동시화 마케팅","불규칙한 수요를 맞추는 것은 동시화 마케팅이다"],["자극적 마케팅","무수요를 일으키는 것은 자극적 마케팅이다"],["인구통계적 기준","나이·성별·소득은 인구통계적 기준이다"],["심리도식적 기준","라이프스타일·성격은 심리도식적 기준이다"],["행동적 기준","사용 상황·추구 편익·사용량은 행동적 세분화 기준이다"],["지리적 기준","지역은 지리적 기준이다"],["효과적 세분화 요건","측정 가능성, 접근 가능성, 충분한 규모(실체성), 실행 가능성이 필요하다 · 세분시장 안은 동질적이고 세분시장 사이는 이질적이어야 하며 기업과의 적합성은 높아야 한다"]]},{"t":"table","title":"표적시장과 혁신 확산","head":["구분","내용"],"rows":[["무차별 마케팅","하나의 제품으로 전체 시장을 공략한다"],["차별적 마케팅","여러 세분시장에 각각 다른 믹스를 공략한다"],["집중 마케팅","하나의 세분시장을 공략한다"],["포지셔닝","표적고객의 마음속에 경쟁 제품과 구별되는 자리를 차지하는 것이다"],["로저스의 수용자","혁신소비자, 조기수용자, 조기다수자, 후기다수자, 지각수용자로 나눴다"],["혁신소비자·조기수용자","혁신소비자는 위험을 감수하고, 조기수용자의 긍정적 구전이 시장 확대의 열쇠다"],["후기다수자","의심이 많아 절반 이상이 구매한 뒤 산다"],["도입기 광고","혁신소비자에게 편익과 인지도를 알리는 데 초점을 둔다"]]},{"t":"table","title":"소비자 구매행동","head":["구분","내용"],"rows":[["구매의사결정","문제 인식, 정보 탐색, 대안 평가, 구매, 구매 후 행동 순이다"],["복잡한 구매행동","관여도가 높고 브랜드 차이가 크면 나타난다"],["부조화 감소 구매행동","관여도가 높고 차이가 작으면 나타난다"],["다양성 추구","관여도가 낮고 차이가 크면 나타난다"],["습관적 구매행동","둘 다 낮으면 나타난다"]]}],"6":[{"t":"table","title":"제품과 서비스","head":["구분","내용"],"rows":[["유형제품","품질·특성·디자인·상표명·포장이다"],["확장제품","보증·배달·설치·대금결제·애프터서비스는 확장제품이다"],["편의품","구매 빈도가 높고 노력이 적어 집중적 유통이다"],["선매품","선매품(의류·가구·가전)은 신중히 비교해 사므로 선택적 유통이다"],["전문품","대체재가 적어 전속적 유통이 맞다"],["비탐색품","강한 광고와 인적판매가 필요하다"],["성장기","수용이 늘어 판매량이 급증하고 단위당 원가와 비용이 떨어져 이익이 빠르게 는다"],["성숙기","경쟁이 가장 치열하다"],["쇠퇴기","판매와 이익이 준다"],["서비스의 특성","무형성, 비분리성, 이질성, 소멸성이다"]]},{"t":"table","title":"브랜드","head":["구분","내용"],"rows":[["브랜드 자산","브랜드가 만들어 내는 부가가치이고, 켈러는 그 원천을 브랜드 인지도와 브랜드 이미지로 보았다"],["브랜드 이미지","호의적이고 독특하며 강력해야 한다"],["브랜드 확장","기존 브랜드를 다른 제품범주의 신제품에 쓰면 브랜드 확장이다"],["라인 확장","같은 범주 안에서 쓰면 라인 확장이다"],["인그리디언트 브랜딩","부품·원재료의 브랜드를 완제품에 알리는 공동브랜드는 인그리디언트 브랜딩이다"]]},{"t":"table","title":"가격","head":["구분","내용"],"rows":[["가격의 특징","가격은 다른 믹스 요소보다 쉽게 바꿀 수 있다"],["준거가격","비싼지 싼지 판단하는 기준 가격이다"],["유보가격","지불할 용의가 있는 최고가격이다"],["JND","가격 변화를 느끼게 하는 최소 폭이다"],["가격-품질 연상","비쌀수록 품질이 좋다고 믿는 것이다"],["종속제품 가격결정","프린터를 싸게 팔고 토너를 비싸게 파는 것은 종속제품 가격결정이다"],["이분 가격","서비스의 낮은 기본요금과 사용수수료 결합은 이분 가격이다"],["심리적 가격결정","단수·준거·명성·관습가격은 심리적 가격결정이다"],["세분시장별 가격결정","고객집단·제품형태·입지·시간에 따라 값을 달리하는 것은 세분시장별 가격결정이다"],["묶음가격","세분시장별 가격결정에 들지 않는다"],["스키밍","신제품 초기에 높은 값으로 시작하면 스키밍이다"],["침투 가격","낮은 값으로 점유율을 높이면 침투 가격이다"]]},{"t":"table","title":"유통경로와 촉진","head":["구분","내용"],"rows":[["수직적 마케팅시스템","소유·통제 정도에 따라 관리형, 계약형, 기업형으로 나뉘고 기업형의 통제력이 가장 강하다"],["기업형","전방·후방통합이다"],["계약형","도매상 후원 자발적 연쇄점·소매상 협동조합·프랜차이즈다"],["관리형","경로리더의 규모와 힘으로 조정된다"],["수평적 마케팅시스템","같은 단계 기업끼리 제휴하면 수평적 마케팅시스템이다"],["프랜차이즈 가맹점","브랜드와 지원을 받지만 자율성이 낮다"],["가격수단 판촉","할인쿠폰, 보상판매, 보너스팩, 리베이트는 구입가격을 낮추는 가격수단 판촉이다"],["비가격수단 판촉","샘플은 비가격수단이다"],["효과계층모델","라비즈와 스테이너의 효과계층모델은 인지, 지식, 호의, 선호, 확신, 구매의 6단계다"]]}],"7":[{"t":"flow","title":"마케팅조사 절차","steps":["문제 정의","조사 설계","자료 수집","자료 분석","보고서 작성 순으로 진행한다 · 문제 정의가 잘못되면 이후 단계가 모두 의미를 잃는다"]},{"t":"table","title":"조사 유형과 자료","head":["구분","내용"],"rows":[["탐색조사","문제를 명확히 하려는 예비조사로 문헌조사·전문가 의견조사·사례조사가 있다"],["기술조사","현상의 특성을 서술하며 횡단조사와 종단(패널)조사가 있다"],["인과조사","변수 사이의 원인과 결과를 실험으로 밝힌다"],["2차 자료","다른 목적으로 이미 수집된 자료로 빠르고 싸지만 현재 문제에 꼭 맞지 않을 수 있다"],["1차 자료","현재 조사 목적을 위해 직접 수집하는 자료로 관찰, 설문, 실험으로 얻는다 · 보통 2차 자료를 먼저 검토한다"]]},{"t":"table","title":"측정 척도","head":["척도","내용"],"rows":[["명목척도","분류만 한다 · 성별은 명목이다"],["서열척도","순위 · 선호 순위는 서열이다"],["등간척도","간격이 같아 덧셈·뺄셈이 가능하다 · 온도는 등간이다"],["비율척도","절대 0이 있어 비율 비교까지 가능하다 · 소득·무게는 비율척도다"]]},{"t":"table","title":"신뢰성·타당성·표본추출","head":["구분","내용"],"rows":[["신뢰성","반복 측정해도 같은 결과가 나오는 정도이다"],["타당성","측정하려는 개념을 제대로 측정하는 정도다"],["신뢰성과 타당성의 관계","타당성이 있으면 신뢰성이 있지만 신뢰성이 있다고 타당성이 보장되지는 않는다"],["확률표본추출","단순무작위·층화·군집·체계적 추출이다"],["비확률표본추출","편의·판단·할당·눈덩이 추출이다"],["층화추출","집단 내 동질·집단 간 이질이 되도록 나눈다"],["군집추출","집단 내 이질·집단 간 동질이 되도록 나눈다"]]}],"8":[{"t":"table","title":"경쟁우선순위·공정·수요예측","head":["구분","내용"],"rows":[["경쟁우선순위","생산의 경쟁우선순위는 원가, 품질, 시간(납기), 유연성이다"],["공정-제품 매트릭스","프로젝트공정은 고객 맞춤형, 개별공정은 다양한 제품, 뱃치공정은 중간 규모, 조립라인공정은 소수 주력 제품의 대량생산, 연속공정은 표준화된 일용품에 맞는다"],["라인밸런싱","작업장 간 작업시간을 균등하게 해 유휴시간을 줄이는 것이다"],["정성적 기법","델파이, 패널동의, 판매원 의견종합, 자료유추는 정성적 기법이고, 회귀분석은 인과형 기법이다"],["가중이동평균","최근 값에 큰 가중치를 곱해 더한다"],["MAD와 MSE","MAD는 절대오차의 평균, MSE는 오차 제곱의 평균이라 큰 오차에 더 민감하다"],["추적지표","누적예측오차를 MAD로 나눈 값으로 예측의 편향을 감지한다"]]},{"t":"table","title":"경제적 주문량과 재고관리","head":["구분","내용"],"rows":[["EOQ","EOQ = √(2 × 연간수요 × 1회 주문비용 ÷ 단위당 연간 재고유지비용)이다 · 연간 재고유지비용과 주문비용의 합이 최소가 되고 두 비용이 같아지는 점이다"],["EOQ의 변화","수요나 주문비용이 늘면 EOQ가 커지고, 재고유지비용이 줄면 EOQ가 커진다"],["정량발주(Q-시스템)","재고를 계속 확인하다 재주문점에 이르면 일정량(EOQ)을 주문하므로 주문량이 일정하고 간격이 변한다"],["정기발주(P-시스템)","일정 주기마다 목표재고에서 현재고를 뺀 만큼 주문하므로 주문량이 변하고 주문 사이 통제가 약하다"],["서비스 수준","리드타임 동안 품절이 나지 않을 확률(충족률)이다"],["ABC 관리","금액 비중이 큰 품목을 집중 관리한다"]]},{"t":"table","title":"MRP·JIT·린과 품질","head":["구분","내용"],"rows":[["MRP","기준생산계획, 자재명세서, 재고기록으로 필요한 자재의 양과 시기를 계산한다"],["JIT","준비시간·준비비용을 줄여 로트 크기를 줄이고 과잉생산을 허용하지 않으며 재공품을 최소로 하면서 작업흐름을 균형화하고 안정된 생산계획이 필요하다 · 품질은 품질관리부서보다 작업자 책임을 강조한다"],["린 생산","낭비를 제거해 부가가치를 높인다"],["외부 실패비용","고객에게 간 뒤 드러난 불량으로 생기는 고객불만·보증·반품·제조물책임 비용이다"],["내부 실패비용","스크랩·재작업은 내부 실패비용이다"],["SERVQUAL","유형성, 신뢰성, 반응성, 확신성, 공감성의 5차원이다"],["가치공학","기능을 유지하며 불필요한 특성 제거, 부품 결합, 무게 감소로 원가를 낮춘다"],["ISO 9001","자율 인증이라 법적 검토사항이 아니다"]]},{"t":"table","title":"공급사슬관리","head":["구분","내용"],"rows":[["채찍효과","하류의 작은 수요 변동이 상류로 갈수록 커지는 현상으로 수요예측 갱신, 리드타임, 뱃치주문, 가격변동, 품귀 시 과잉주문이 원인이다"],["효율성 지표","공급사슬 효율성 지표는 재고회전율이다"],["효율적 공급사슬","기능적 제품에 맞으며 가동률과 재고회전율을 높이고 여유능력을 적게 둔다"],["대응적 공급사슬","리드타임 단축에 과감히 투자하는 것은 대응적 공급사슬이다"],["학습곡선","누적생산량이 늘수록 단위원가가 떨어지는 현상은 학습곡선이다"]]}],"9":[{"t":"table","title":"ERP·SCM·CRM","head":["시스템","내용"],"rows":[["ERP","기업 전체의 업무를 하나의 시스템으로 통합해 프로세스를 표준화·단순화하고 정보를 실시간으로 공유하게 한다"],["ERP의 도입 효과","업무프로세스가 복잡해지는 것은 도입 효과가 아니다"],["SCM","공급사슬 전체를 관리한다"],["CRM","고객 관계를 관리한다"]]},{"t":"table","title":"빅데이터와 컴퓨팅","head":["구분","내용"],"rows":[["빅데이터의 3V","규모(volume), 다양성(variety), 속도(velocity)다"],["텍스트마이닝","비정형 텍스트에서 의미를 뽑아내는 기법은 텍스트마이닝이다"],["클라우드 컴퓨팅","공유된 컴퓨팅 자원을 인터넷으로 필요할 때 빌려 쓰는 방식이다"],["온프레미스","자원을 직접 설치해 운영한다"],["엣지 컴퓨팅","데이터가 생기는 곳 가까운 말단 서버에서 일부를 처리해 지연과 클라우드 부담을 줄인다"]]},{"t":"table","title":"모바일·무선기술","head":["구분","내용"],"rows":[["모바일 비즈니스","편재성, 접근성, 편리성, 접속성이 특징이다"],["고정성","모바일 비즈니스의 특징에 해당하지 않는다"],["NFC","10cm 안팎의 근거리에서 데이터를 주고받아 모바일 결제에 쓰인다"]]},{"t":"table","title":"정보보안 위협과 인공지능","head":["구분","내용"],"rows":[["피싱","기업·금융기관을 사칭한 메일로 개인정보를 빼낸다"],["파밍","정상 주소를 입력해도 가짜 사이트로 보낸다"],["스니핑","네트워크 패킷을 엿듣는다"],["서비스 거부 공격","과도한 접속으로 서비스를 마비시킨다"],["웜","스스로 복제해 퍼진다"],["지능형 에이전트","사용자를 대신해 정보를 찾고 비교하는 소프트웨어로 쇼핑봇이 대표적이다"],["기계학습","데이터로 규칙을 학습한다"],["딥러닝","다층 신경망을 쓰는 기계학습이다"]]}],"10":[{"t":"table","title":"현재가치와 미래가치","head":["구분","내용"],"rows":[["미래가치·현재가치","미래가치 FV = PV × (1 + r)^n, 현재가치 PV = FV ÷ (1 + r)^n이다"],["연금","매기 C를 받는 n기 연금의 현재가치는 C × [1 − 1/(1 + r)^n] ÷ r이다"],["영구연금","영구연금은 C ÷ r이다"],["성장 영구연금","매년 g씩 성장하는 영구연금은 C1 ÷ (r − g)다"]]},{"t":"table","title":"채권가격과 유효이자율법","head":["구분","내용"],"rows":[["채권가격","이자와 액면금액을 만기수익률로 할인한 현재가치의 합이다"],["할인발행·할증발행","시장이자율이 액면이자율보다 높으면 할인발행, 낮으면 할증발행이다"],["이자율과 채권가격","이자율이 오르면 채권가격은 떨어지고, 만기가 길수록 가격 변동이 크다"],["사채 발행가액","액면금액의 현재가치와 액면이자의 연금 현재가치를 더한 값이다"],["이자비용","장부금액에 발행 당시 시장이자율(유효이자율)을 곱해 구하고, 할인발행이면 이자비용이 액면이자보다 크다"],["계산 예","액면 1,000,000원, 액면이자 8%, 시장이자율 10%, 5년이면 발행가액은 923,200원이고 첫해 이자비용은 92,320원이다"]]},{"t":"table","title":"듀레이션","head":["구분","내용"],"rows":[["듀레이션","각 시점 현금흐름의 현재가치를 가중치로 한 가중평균 회수기간이다"],["무이표채","듀레이션은 만기와 같다"],["이표채","듀레이션은 만기보다 짧다"],["듀레이션의 변화","액면이자율과 만기수익률이 높을수록 듀레이션이 짧아지고, 듀레이션이 길수록 이자율 변화에 대한 가격 민감도가 크다"],["계산 예","액면이자 10%, 만기수익률 12%인 2년 채권은 약 1.91년이다"]]},{"t":"table","title":"이자율 기간구조","head":["구분","내용"],"rows":[["기대이론","장기이자율이 미래 단기이자율 기대치의 평균이라고 본다"],["유동성프리미엄이론","장기채에 위험 보상이 더해진다고 본다"],["수익률곡선","우상향이면 장기금리가 단기금리보다 높다"]]}],"11":[{"t":"vs","title":"시간가치 고려 여부","cols":[{"name":"시간가치를 고려","items":["순현재가치법, 내부수익률법, 수익성지수법은 현금흐름을 할인하므로 화폐의 시간가치를 고려한다"]},{"name":"시간가치를 고려하지 않음","items":["회수기간법과 회계적이익률법은 할인하지 않는다"]}]},{"t":"table","title":"회수기간법과 회계적이익률법","head":["구분","내용"],"rows":[["회수기간법","투자액을 회수하는 기간이 짧은 투자안을 고르며 회수기간 이후의 현금흐름은 무시한다"],["회계적이익률","연평균 순이익을 연평균 투자액으로 나눈 값이다"]]},{"t":"table","title":"NPV와 IRR","head":["구분","내용"],"rows":[["순현재가치법(NPV)","현금유입의 현재가치에서 투자액을 뺀 값이고 0보다 크면 채택한다"],["NPV의 가정","재투자수익률을 자본비용으로 가정하고, 여러 투자안의 NPV를 더할 수 있는 가치가산의 원칙이 성립한다"],["NPV의 평가","기업가치 극대화와 일치하므로 가장 우수한 방법으로 본다"],["내부수익률법(IRR)","NPV를 0으로 만드는 할인율이고 자본비용보다 크면 채택한다"],["IRR의 가정","재투자수익률을 내부수익률로 가정하며 현금흐름 부호가 여러 번 바뀌면 복수의 IRR이 생길 수 있다"],["투자형 현금흐름","투자형 현금흐름에서는 투자수익률을 뜻한다"]]},{"t":"table","title":"수익성지수법","head":["구분","내용"],"rows":[["수익성지수(PI)","현금유입의 현재가치를 투자액으로 나눈 값이고 1보다 크면 채택한다"],["NPV와의 관계","NPV = 투자액 × (PI − 1)이므로 규모가 다른 상호배타적 투자안에서는 NPV와 결론이 다를 수 있다"],["계산 예","투자액 200·300·400억원, PI 1.5·1.2·1.3이면 NPV는 100·60·120억원이다"]]}],"12":[{"t":"table","title":"포트폴리오 이론","head":["구분","내용"],"rows":[["기대수익률","포트폴리오 기대수익률은 개별 기대수익률의 가중평균이다"],["분산","두 자산이면 분산은 wA²σA² + wB²σB² + 2wAwBρσAσB이고, 상관계수가 1보다 작으면 분산투자로 위험이 준다"],["계산 예","분산 0.06과 0.08, 상관계수 0, 절반씩 투자하면 분산은 0.035다"]]},{"t":"vs","title":"체계적 위험과 비체계적 위험","cols":[{"name":"비체계적 위험","items":["분산투자로 없앨 수 있는 위험은 비체계적(기업 고유) 위험이다"]},{"name":"체계적 위험","items":["없앨 수 없는 시장 전체 위험은 체계적 위험이다","체계적 위험은 베타로 측정하며 시장포트폴리오의 베타는 1이다"]}]},{"t":"table","title":"CAPM의 가정","head":["구분","내용"],"rows":[["투자자","투자자는 위험회피적이고 기대효용을 극대화하며 평균-분산 기준으로 선택한다"],["자금","무위험이자율로 무제한 차입·대출이 가능하다"],["시장","세금과 거래비용이 없는 완전자본시장이며, 모든 투자자가 동질적 기대를 한다"]]},{"t":"vs","title":"CML과 SML","cols":[{"name":"자본시장선(CML)","items":["무위험자산과 시장포트폴리오를 결합한 효율적 투자기회선이고 효율적 포트폴리오의 총위험(표준편차)과 기대수익률의 관계를 나타낸다","기울기는 [E(Rm) − Rf] ÷ σm이고, CML 위의 포트폴리오에는 비체계적 위험이 없다","시장과 상관계수가 1인 포트폴리오는 CML 위에 있다"]},{"name":"증권시장선(SML)","items":["E(Ri) = Rf + βi × [E(Rm) − Rf]로 개별자산과 비효율적 포트폴리오까지 포함해 기대수익률과 베타의 관계를 나타낸다","SML 위에 있으면 과소평가, 아래에 있으면 과대평가된 자산이다","균형에서는 모든 자산의 베타 대비 초과수익률이 같고, 베타가 같으면 SML 위 같은 점에 놓인다","Rf 5%, E(Rm) 10%, β 1.2이면 11%다"]},{"name":"APT","items":["차익거래가격결정이론은 여러 공통요인에 대한 민감도로 기대수익률을 설명하며 시장포트폴리오나 정규분포 가정이 필요 없다","차익거래 기회가 없도록 가격이 결정된다"]}]}],"13":[{"t":"table","title":"가중평균자본비용(WACC)","head":["구분","내용"],"rows":[["WACC","WACC = (E/V) × ke + (D/V) × kd × (1 − t)이다"],["타인자본비용","타인자본비용에는 이자의 법인세 절감효과가 반영된다"],["계산 예","자기자본·타인자본 각 5억원, ke 16%, kd 12%, 법인세율 50%이면 WACC는 11%다"]]},{"t":"vs","title":"MM 이론","cols":[{"name":"법인세가 없는 MM(1958)","items":["자본구조가 기업가치에 영향을 주지 않는다"]},{"name":"법인세가 있는 MM(1963)","items":["부채의 이자 절세효과만큼 부채기업 가치가 커져 부채를 많이 쓸수록 유리하다","부채기업 가치 = 무부채기업 가치 + 법인세율 × 부채다"]}]},{"t":"table","title":"자본구조 이론과 레버리지","head":["구분","내용"],"rows":[["상충이론","부채의 절세효과와 파산비용·대리비용을 비교해 최적 자본구조가 있다고 본다"],["자본조달순서이론","내부자금, 부채, 신주 순으로 조달한다고 본다"],["무부채기업의 자기자본비용","CAPM으로 구하며 베타 0.6, Rf 10%, E(Rm) 12%이면 11.2%다"],["영업레버리지도(DOL)","공헌이익 ÷ 영업이익으로 고정영업비가 클수록 커진다"],["재무레버리지도(DFL)","영업이익 ÷ (영업이익 − 이자비용)이다"],["결합레버리지도","DOL × DFL이다"],["계산 예","2,000개, 단가 10,000원, 단위 변동비 1,000원, 고정비 3,000,000원이면 DOL은 1.2다"]]},{"t":"table","title":"배당정책","head":["이론","내용"],"rows":[["MM의 배당무관련이론","세금·거래비용이 없는 완전자본시장, 정보의 자유로운 이용, 확실한 이익·배당 예측을 가정하며 배당소득과 자본차익이 같은 가치라고 본다"],["고든의 배당모형","투자자가 불확실한 자본이득보다 확실한 배당을 선호한다고 본다"],["신호이론","배당 증가가 좋은 전망의 신호라고 본다"]]}],"14":[{"t":"table","title":"배당할인모형과 상대가치평가","head":["구분","내용"],"rows":[["배당할인모형","주가는 미래 배당의 현재가치다"],["영구 성장","매년 g씩 영구 성장하면 P0 = D1 ÷ (r − g)이고, 요구수익률 r = D1 ÷ P0 + g다"],["계산 예","D0 5,000원, g 5%, r 10%이면 D1은 5,250원이고 주가는 105,000원이다"],["PER와 PBR","PER는 주가 ÷ 주당순이익, PBR은 주가 ÷ 주당순자산이다"],["상대가치평가","비교기업의 배수에 평가 대상의 이익이나 순자산을 곱해 가치를 추정한다"]]},{"t":"table","title":"효율적 시장가설","head":["형태","내용"],"rows":[["약형","과거 주가 정보가 주가에 반영되었다고 본다 · 약형이 성립하면 기술적 분석으로 초과수익을 얻을 수 없다"],["준강형","공개된 모든 정보가 주가에 반영되었다고 본다 · 준강형이 성립하면 기본적 분석으로 초과수익을 얻을 수 없다"],["강형","내부정보까지 주가에 반영되었다고 본다"]]},{"t":"table","title":"M&A 방식","head":["구분","내용"],"rows":[["공개매수(TOB)","매수 기간·가격·수량을 공개하고 시장 밖에서 주주에게서 주식을 사들이는 방법이다"],["LBO","피인수기업 자산을 담보로 차입해 인수한다"],["MBO","경영진이 회사를 인수한다"],["수평적 합병","같은 업종의 결합이다"],["수직적 합병","생산·유통 단계가 다른 기업의 결합이다"],["복합합병","관련 없는 업종의 결합이다"]]},{"t":"table","title":"적대적 M&A 방어","head":["방어책","내용"],"rows":[["포이즌 필","기존 주주에게 싼값에 신주를 사게 해 인수 비용을 높인다"],["황금낙하산","경영진 해임 시 거액 보상을 약속한다"],["백기사","우호적 제3자에게 회사를 넘기는 방어책이다"]]}],"15":[{"t":"vs","title":"옵션과 선물","cols":[{"name":"옵션","items":["특정 자산을 정해진 가격으로 정해진 날(또는 그 전)에 사거나 팔 수 있는 권리이다","옵션 매수자는 프리미엄을 내고 권리를 얻으며 매도자는 의무를 진다"]},{"name":"선물","items":["정해진 날에 거래해야 하는 의무다"]}]},{"t":"table","title":"콜옵션과 풋옵션","head":["구분","내용"],"rows":[["콜옵션","살 권리다 · 만기에 콜의 가치는 max(S − X, 0)이다"],["풋옵션","팔 권리다 · 만기에 풋의 가치는 max(X − S, 0)이다"],["유럽형","만기일에만 행사할 수 있으면 유럽형이다"],["미국형","만기 전 언제든 행사할 수 있으면 미국형이다"]]},{"t":"table","title":"옵션가격 결정요인","head":["구분","내용"],"rows":[["기초자산 가격","기초자산 가격이 오르면 콜 가치는 오르고 풋 가치는 내린다"],["행사가격","행사가격이 높을수록 콜은 싸고 풋은 비싸다"],["변동성","변동성이 클수록 콜과 풋 모두 가치가 커진다"],["풋-콜 패리티","S + P = C + X/(1 + r)^T이다"]]},{"t":"table","title":"선물거래와 스왑","head":["구분","내용"],"rows":[["선물","거래소에서 표준화된 조건으로 거래되고 일일정산과 증거금 제도가 있다"],["선도","장외에서 당사자가 조건을 정한다"],["매도헤지","보유 현물의 가격 하락이 걱정되면 선물을 매도하는 매도헤지를 한다"],["금리스왑","고정금리와 변동금리 이자 지급을 교환한다"],["통화스왑","서로 다른 통화의 원금과 이자를 교환한다"],["비교우위","비교우위가 있는 시장에서 조달해 교환하면 양쪽 모두 조달비용을 줄일 수 있다"]]}],"16":[{"t":"table","title":"환율 표시와 구매력평가설","head":["구분","내용"],"rows":[["자국통화 표시법","외국통화 1단위를 사는 데 드는 자국통화 금액이다 · 원/달러 환율이 오르면 원화가치가 떨어진 것(원화 절하)이다"],["절대적 구매력평가","같은 상품의 가격이 어느 나라에서나 같아지도록 환율이 정해진다고 본다"],["상대적 구매력평가","환율 변화율이 두 나라 물가상승률의 차이와 같다고 본다"]]},{"t":"table","title":"이자율평가설","head":["구분","내용"],"rows":[["이자율평가설","선물환율과 현물환율의 차이가 두 나라 이자율 차이로 정해진다고 본다"],["외화 선물환 할증","자국 이자율이 외국보다 높으면 선물환율이 현물환율보다 높다(외화 선물환 할증)"],["피셔효과","명목이자율이 실질이자율과 기대인플레이션의 합이라고 본다"]]},{"t":"table","title":"환위험 관리","head":["구분","내용"],"rows":[["환노출","거래적·환산적·경제적 노출로 나뉜다"],["외화 수취 예정","선물환 매도로 환율을 고정한다"],["외화 지급 예정","선물환 매수를 한다"],["내부적 관리기법","리딩·래깅, 매칭, 네팅이다"],["외부적 관리기법","선물환·통화선물·통화옵션·통화스왑이다"]]},{"t":"table","title":"위험관리 기법","head":["구분","내용"],"rows":[["위험관리","위험 회피, 위험 감소, 위험 전가(보험·헤지), 위험 보유로 대응한다"],["VaR","주어진 신뢰수준에서 일정 기간 동안 생길 수 있는 최대 손실액이다"]]}],"17":[{"t":"table","title":"계정 분류와 자본 구성","head":["구분","내용"],"rows":[["자산 계정","미수금·대여금·선급금·선급비용·미수수익·영업권은 자산이다"],["부채 계정","매입채무·사채·선수금·선수수익·미지급비용·예수금은 부채다"],["예수금","급여 지급 때 근로자 몫 4대 보험료를 떼어 두는 계정은 예수금이다"],["자기주식처분이익","자본잉여금이어서 포괄손익계산서 계정이 아니다"],["자본","자본금, 자본잉여금(주식발행초과금, 자기주식처분이익), 자본조정(자기주식, 주식할인발행차금, 미교부주식배당금), 기타포괄손익누계액, 이익잉여금(이익준비금 등 법정적립금, 임의적립금, 미처분이익잉여금)이다"],["자기주식","재발행 목적으로 다시 사들인 자사 주식은 자기주식으로 자본에서 차감한다"]]},{"t":"vs","title":"분개의 차변과 대변","cols":[{"name":"차변","items":["자산 증가·부채 감소·자본 감소·비용 발생","미수수익 증가와 급여 지급"]},{"name":"대변","items":["자산 감소·부채 증가·자본 증가·수익 발생","매입채무·선수금 증가와 임대료 수익"]}]},{"t":"table","title":"자본 변동 계산과 마감","head":["구분","내용"],"rows":[["명목계정","수익·비용 같은 명목계정은 마감 후 이월되지 않고, 재무상태표 계정은 이월된다"],["기초자본","기초자본 = 기초자산 − 기초부채이다"],["기말자본","기말자본 = 기초자본 + 유상증자 − 현금배당 + 당기순이익이다"],["계산 예","기초자산 380,000원, 기초부채 180,000원, 증자 80,000원, 배당 40,000원, 순이익 100,000원이면 기말자본은 340,000원이다"]]},{"t":"table","title":"유형자산·감가상각·기타","head":["구분","내용"],"rows":[["취득원가","매입가격, 설치·조립원가, 최초 운송·취급원가, 직접 관련 종업원급여, 환급 불가능한 관세가 들어간다"],["비용 처리","소모품 교체·원상복구·도색 같은 수선유지비, 취득 후 보험료, 새 상품을 소개하는 원가는 비용이다"],["토지 재평가","앞서 당기손실로 인식한 감소분까지의 증가는 당기이익, 그 초과분은 재평가잉여금이다"],["감가상각","감가상각은 자산 평가가 아니라 원가배분 과정이고 토지는 상각하지 않는다"],["정액법·정률법","정액법은 (취득원가 − 잔존가치) ÷ 내용연수, 정률법은 기초 장부금액 × 상각률이라 초반에 많이 상각한다"],["감가상각누계액","지금까지 인식한 상각비 누적액이다"],["계산 예","2,000,000원, 잔존 200,000원, 5년 정액법 기계를 2년 뒤 1,300,000원에 팔면 처분이익은 20,000원이다"],["매출원가","매출원가 = 기초재고 + 당기매입 − 기말재고이고, 매출총이익률법은 매출원가를 추정해 기말재고를 역산한다"],["영업권","이전대가에서 피취득자 순자산 공정가치를 뺀 금액이고, 음수면 염가매수차익이다"],["감사의견","적정, 한정, 부적정, 의견거절이다"]]}],"18":[{"t":"table","title":"유동성·안정성 비율","head":["구분","내용"],"rows":[["유동비율","유동비율 = 유동자산 ÷ 유동부채이다"],["당좌비율","당좌비율 = 당좌자산(유동자산 − 재고자산) ÷ 유동부채다"],["계산 예","유동자산 1,200,000원, 유동비율 200%, 당좌비율 150%이면 유동부채 600,000원, 당좌자산 900,000원, 재고자산 300,000원이다"],["부채비율","부채 ÷ 자기자본이다"],["이자보상비율","영업이익 ÷ 이자비용으로 이자 지급의 안전도를 나타낸다"]]},{"t":"table","title":"활동성·수익성 비율","head":["구분","내용"],"rows":[["활동성비율","자산 이용의 효율성을 재며 총자산회전율 = 매출액 ÷ 총자산, 재고자산회전율 = 매출원가(또는 매출액) ÷ 평균재고다"],["ROA","순이익 ÷ 총자산이다"],["ROE","순이익 ÷ 자기자본으로 주주 관점의 수익성이다"]]},{"t":"table","title":"듀퐁 분석과 한계","head":["구분","내용"],"rows":[["듀퐁 분석","ROA = 매출액순이익률 × 총자산회전율이고, ROE = ROA × (1 + 부채비율)이다"],["계산 예","ROA 20%, 매출액순이익률 8%이면 총자산회전율은 2.5다"],["비율분석의 한계","기업마다 회계처리 방법이 달라 비교할 때 이를 고려해야 하고, 과거 자료라는 한계가 있다"]]}],"19":[{"t":"vs","title":"원가 행태","cols":[{"name":"변동비","items":["조업도에 비례해 총액이 변하고 단위당 금액은 일정하다"]},{"name":"고정비","items":["일정 범위에서 총액이 일정하고 단위당 금액은 조업도가 늘수록 준다"]}]},{"t":"table","title":"공헌이익과 이익","head":["구분","내용"],"rows":[["단위당 공헌이익","단위당 공헌이익 = 판매가격 − 단위당 변동비이다"],["공헌이익률","공헌이익률 = 단위당 공헌이익 ÷ 판매가격이다"],["공헌이익의 쓰임","공헌이익은 고정비를 회수하고 이익을 내는 데 쓰인다"],["영업이익","영업이익 = 판매량 × (판매가격 − 단위당 변동비) − 고정비다"],["계산 예","고정비 1,000원, 단위 변동비 50원, 판매가 300원, 10대 판매이면 이익은 1,500원이다"]]},{"t":"table","title":"손익분기점과 안전한계","head":["구분","내용"],"rows":[["손익분기점 판매량","손익분기점 판매량 = 고정비 ÷ 단위당 공헌이익이다"],["손익분기점 매출액","손익분기점 매출액 = 고정비 ÷ 공헌이익률이다"],["목표이익 판매량","(고정비 + 목표이익) ÷ 단위당 공헌이익이다"],["안전한계","실제 매출액에서 손익분기점 매출액을 뺀 금액이다"],["영업레버리지도","공헌이익 ÷ 영업이익이며 안전한계율의 역수와 같다"]]}]};
